export const TRANSLATIONS: Record<LangCode, Translations> = { en, hi, gu, mr, ta, te, bn, pa }

export function translate(lang: LangCode, key: TranslationKey): string {
  return TRANSLATIONS[lang]?.[key] ?? TRANSLATIONS.en[key] ?? key
}
